def sort_and_dedupe_by_score(records):
    best = {}

    for r in records:
        if "id" not in r:
            continue

        score = r.get("score")
        try:
            score = float(score)
        except (TypeError, ValueError):
            continue

        rid = r["id"]
        if rid not in best or score > best[rid]["score"]:
            best[rid] = {**r, "score": score}

    return sorted(best.values(), key=lambda x: x["score"])


# Example
data = [
    {"id": 1, "name": "Alice", "score": 88},
    {"id": 2, "name": "Bob", "score": "72"},
    {"id": 1, "name": "Alice", "score": 91},   # duplicate id, higher score wins
    {"id": 3, "name": "Charlie", "score": None}, # skipped
    {"id": 4, "name": "Dana", "score": "bad"},  # skipped
    {"id": 2, "name": "Bob", "score": 70},      # duplicate id, lower score ignored
]

result = sort_and_dedupe_by_score(data)
print(result)
